1	import { NativeStackScreenProps } from '@react-navigation/native-stack';
2	import { Check } from 'lucide-react-native';
3	import { nanoid } from 'nanoid/non-secure';
4	import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
5	import {
6	  ActivityIndicator,
7	  FlatList,
8	  KeyboardAvoidingView,
9	  Platform,
10	  RefreshControl,
11	  ScrollView,
12	  StyleSheet,
13	  TextInput,
14	  View,
15	} from 'react-native';
16	import {
17	  AppBar,
18	  Button,
19	  Card,
20	  Chip,
21	  QtyStepper,
22	  radius,
23	  Skeleton,
24	  spacing,
25	  Text,
26	} from '../../../design';
27	import { enqueue } from '../../../db/outbox';
28	import { adjustOnHand, findStock, getNearestExpiry, listStock, replaceStockFromRemote, StockRow, statusFor } from '../../../db/stock';
29	import { decrementLotsLocal, listLots, pruneLotsToBarcodes, replaceLotsLocal } from '../../../db/lots';
30	import { LotAllocation, LotPicker, suggestFEFO } from '../components/LotPicker';
31	import { getSession } from '../../../auth/session';
32	import { useT } from '../../../i18n';
33	import { StringKey } from '../../../i18n/strings';
34	import { RootStackParamList } from '../../../navigation/types';
35	import { api, ApiError } from '../../../sync/api';
36	import { flushOnce } from '../../../sync/syncService';
37	import { invalidateRefetchThrottle, refetchThrottled } from '../../../sync/refetch';
38	import { haptic } from '../../../utils/haptics';
39	import { useKeyboardHeight } from '../../../hooks/useKeyboardHeight';
40	import { FilterDropdown, FilterOption } from '../components/FilterDropdown';
41	import { useTheme } from '../../../theme';
42	
43	type Props = NativeStackScreenProps<RootStackParamList, 'Dispense'>;
44	
45	// `value` is the canonical English string recorded on the dispense; only
46	// the displayed label is translated, so reporting/grouping stays stable
47	// regardless of the guard's chosen language.
48	const REASONS: { value: string; labelKey: StringKey }[] = [
49	  { value: 'Office use', labelKey: 'reasonOfficeUse' },
50	  { value: 'Pantry', labelKey: 'reasonPantry' },
51	  { value: 'Cleaning', labelKey: 'reasonCleaning' },
52	  { value: 'Maintenance', labelKey: 'reasonMaintenance' },
53	  { value: 'Other', labelKey: 'reasonOther' },
54	];
55	
56	// Stable keys drive the filter logic; labels are resolved per-render.
57	const STATUS_OPTIONS: { key: string; labelKey: StringKey }[] = [
58	  { key: 'All', labelKey: 'statusAll' },
59	  { key: 'In Stock', labelKey: 'statusInStock' },
60	  { key: 'Low', labelKey: 'statusLow' },
61	  { key: 'Out', labelKey: 'statusOut' },
62	];
63	
64	type VerifyStatus = 'verifying' | 'ok' | 'absent' | 'offline' | 'error';
65	
66	function isOfflineError(err: unknown): boolean {
67	  const msg = err instanceof Error ? err.message : String(err);
68	  return (
69	    msg.includes('Network request failed') ||
70	    msg.includes('TypeError: Network') ||
71	    msg.includes('Unable to resolve host')
72	  );
73	}
74	
75	/** Subtle background tint per stock health */
76	function cardBg(row: StockRow): string {
77	  const s = statusFor(row);
78	  if (s === 'out') return 'rgba(229, 57, 53, 0.07)';
79	  if (s === 'low') return 'rgba(249, 168, 37, 0.07)';
80	  if (row.on_hand >= row.threshold * 2) return 'rgba(67, 160, 71, 0.06)';
81	  return 'rgba(129, 199, 132, 0.06)';
82	}
83	
84	/** Count text color per stock health */
85	function countColor(row: StockRow): string {
86	  const s = statusFor(row);
87	  if (s === 'out') return '#E53935';
88	  if (s === 'low') return '#F9A825';
89	  if (row.on_hand >= row.threshold * 2) return '#43A047';
90	  return '#66BB6A';
91	}
92	
93	export function DispenseScreen({ route, navigation }: Props) {
94	  const t = useT();
95	  const { palette } = useTheme();
96	  const kbHeight = useKeyboardHeight();
97	  const initialBarcode = route.params?.barcode;
98	  const [selected, setSelected] = useState<StockRow | null>(null);
99	  const [all, setAll] = useState<StockRow[]>([]);
100	  const [query, setQuery] = useState('');
101	  const [category, setCategory] = useState('All');
102	  const [statusFilter, setStatusFilter] = useState('All');
103	  const [qty, setQty] = useState(1);
104	  const [reason, setReason] = useState(REASONS[0].value);
105	  const [saving, setSaving] = useState(false);
106	  const [initialLoading, setInitialLoading] = useState(true);
107	  const [refreshing, setRefreshing] = useState(false);
108	
109	  // JIT verification — fetch the server's authoritative on_hand the
110	  // moment a product is selected. Dispense MUST commit against the
111	  // freshest count so we never let a guard dispense 10 from a stock
112	  // of 8. Fail-closed: if the JIT fetch fails or times out, the
113	  // confirm button stays disabled until the user goes back and tries
114	  // again with network.
115	  const [verifyStatus, setVerifyStatus] = useState<VerifyStatus>('verifying');
116	  const [verifiedOnHand, setVerifiedOnHand] = useState<number | null>(null);
117	  /** Per-lot availability + current allocation. FEFO-ordered (earliest
118	   *  first). The big QtyStepper drives `qty` which re-suggests FEFO
119	   *  across these rows; users can override per-lot via the LotPicker
120	   *  (shown only when there are 2+ lots — single-lot products skip the
121	   *  picker). Total taken = sum(allocation.take). */
122	  const [allocation, setAllocation] = useState<LotAllocation[]>([]);
123	  const [availability, setAvailability] = useState<{ expiry: string | null; available: number }[]>([]);
124	
125	  const categoryOptions = useMemo<FilterOption[]>(() => {
126	    const cats = new Set(all.map((r) => r.category).filter(Boolean) as string[]);
127	    return [{ key: 'All', label: t('allCategories') }, ...Array.from(cats).sort().map((c) => ({ key: c, label: c }))];
128	  }, [all, t]);
129	  const statusOptions = useMemo<FilterOption[]>(
130	    () => STATUS_OPTIONS.map((o) => ({ key: o.key, label: t(o.labelKey) })),
131	    [t],
132	  );
133	
134	  // Pull the latest stock from the server and replace the local cache,
135	  // then re-read SQLite into the picker list. Mirrors StockScreen so the
136	  // dispense picker stays in sync with the source of truth — without this
137	  // it only ever showed whatever warmCache last left behind. Shares the
138	  // 'stock' refetch key with Stock/Alerts (same stock_levels table).
139	  const fetchRemote = useCallback(async () => {
140	    await flushOnce().catch(() => {});
141	    const remote = await api.fetch.stock();
142	    await replaceStockFromRemote(
143	      remote.map((r) => ({
144	        barcode: r.barcode,
145	        name: r.name,
146	        category: r.category,
147	        unit: r.unit,
148	        pack_size: r.pack_size != null ? Number(r.pack_size) : null,
149	        dispense_mode: r.dispense_mode ?? 'pack',
150	        on_hand: Number(r.on_hand),
151	        threshold: Number(r.threshold),
152	      })),
153	    );
154	    for (const r of remote) {
155	      await replaceLotsLocal(
156	        r.barcode,
157	        (r.lots ?? []).map((l) => ({ expiry_date: l.expiry_date, qty: Number(l.qty) })),
158	      );
159	    }
160	    await pruneLotsToBarcodes(remote.map((r) => r.barcode));
161	  }, []);
162	
163	  const readLocal = useCallback(async () => {
164	    setAll(await listStock());
165	  }, []);
166	
167	  const refresh = useCallback(async () => {
168	    await refetchThrottled('stock', fetchRemote);
169	    await readLocal();
170	  }, [fetchRemote, readLocal]);
171	
172	  useEffect(() => {
173	    readLocal().then(() => setInitialLoading(false));
174	    void refresh();
175	    const unsub = navigation.addListener('focus', () => { void refresh(); });
176	    return unsub;
177	  }, [navigation, refresh, readLocal]);
178	
179	  const onRefresh = useCallback(async () => {
180	    // Pull-to-refresh is user-initiated — bypass the throttle so a pull
181	    // right after a focus-fetch isn't swallowed.
182	    invalidateRefetchThrottle('stock');
183	    setRefreshing(true);
184	    try {
185	      await refresh();
186	    } finally {
187	      setRefreshing(false);
188	    }
189	  }, [refresh]);
190	
191	  useEffect(() => {
192	    if (initialBarcode) {
193	      findStock(initialBarcode).then((r) => r && setSelected(r));
194	    }
195	  }, [initialBarcode]);
196	
197	  // Whenever an item gets selected, re-run JIT verification. The
198	  // dependency on `selected?.barcode` (not the whole row) means
199	  // refetching only happens for an actual product change, not for the
200	  // optimistic update we apply after submit.
201	  useEffect(() => {
202	    if (!selected) {
203	      setVerifyStatus('verifying');
204	      setVerifiedOnHand(null);
205	      return;
206	    }
207	    let cancelled = false;
208	    setVerifyStatus('verifying');
209	    setVerifiedOnHand(null);
210	    const controller = new AbortController();
211	    const t = setTimeout(() => controller.abort(), 3000);
212	    (async () => {
213	      try {
214	        const remote = await api.fetch.stockOne(selected.barcode);
215	        if (cancelled) return;
216	        const remoteQty = Number(remote.on_hand);
217	        setVerifiedOnHand(remoteQty);
218	        setVerifyStatus('ok');
219	        // Clamp qty to the verified ceiling. If the user had a stale
220	        // higher qty in mind (e.g. local cache said 10, server says 7),
221	        // drop to the new max so they can't accidentally submit over.
222	        const minStep = selected.dispense_mode === 'divisible' ? 0.001 : 1;
223	        const clampedQty = qty > remoteQty ? Math.max(minStep, remoteQty) : qty;
224	        if (clampedQty !== qty) setQty(clampedQty);
225	
226	        // Build the lot picker state. Prefer the remote lots (verified
227	        // truth); fall back to the local lots cache when the server
228	        // returned no breakdown. Final fallback for legacy rows that
229	        // never received a lot write (existed before the lots
230	        // migration): synthesise a single lot from on_hand +
231	        // nearest_expiry so dispense still works on existing inventory.
232	        const remoteLots = remote.lots ?? [];
233	        let lots = remoteLots.length > 0
234	          ? remoteLots
235	          : (await listLots(selected.barcode)).map((l) => ({
236	              expiry_date: l.expiry_date,
237	              qty: Number(l.qty),
238	            }));
239	        if (lots.length === 0 && remoteQty > 0) {
240	          lots = [{
241	            expiry_date: remote.nearest_expiry ?? null,
242	            qty: remoteQty,
243	          }];
244	        }
245	        const nextAvailability = lots.map((l) => ({
246	          expiry: l.expiry_date,
247	          available: Number(l.qty),
248	        }));
249	        setAvailability(nextAvailability);
250	        setAllocation(suggestFEFO(nextAvailability, clampedQty));
251	      } catch (err) {
252	        if (cancelled) return;
253	        // 404: the server has no record of this barcode (might be a
254	        // device-only item never received server-side). Treat as
255	        // "absent" — block dispense; you can't dispense what the
256	        // server doesn't know exists.
257	        if (err instanceof ApiError && err.status === 404) {
258	          setVerifyStatus('absent');
259	          return;
260	        }
261	        if (err instanceof ApiError && err.status === 401) return;
262	
263	        // Couldn't reach the server (offline) or the check failed/timed
264	        // out. Offline-first decision: fall back to the last-known CACHED
265	        // count + local lots so the guard can still dispense. The write
266	        // queues in the outbox and reconciles on sync. Only the 404
267	        // "absent" case above stays blocked — everything else degrades to
268	        // the saved count rather than a dead button.
269	        const cachedQty = selected.on_hand;
270	        setVerifiedOnHand(cachedQty);
271	        const minStep = selected.dispense_mode === 'divisible' ? 0.001 : 1;
272	        const clampedQty = qty > cachedQty ? Math.max(minStep, cachedQty) : qty;
273	        if (clampedQty !== qty) setQty(clampedQty);
274	        let lots = (await listLots(selected.barcode)).map((l) => ({
275	          expiry_date: l.expiry_date,
276	          qty: Number(l.qty),
277	        }));
278	        if (lots.length === 0 && cachedQty > 0) {
279	          lots = [{ expiry_date: await getNearestExpiry(selected.barcode), qty: cachedQty }];
280	        }
281	        if (cancelled) return;
282	        const nextAvailability = lots.map((l) => ({
283	          expiry: l.expiry_date,
284	          available: Number(l.qty),
285	        }));
286	        setAvailability(nextAvailability);
287	        setAllocation(suggestFEFO(nextAvailability, clampedQty));
288	        setVerifyStatus(isOfflineError(err) ? 'offline' : 'error');
289	      } finally {
290	        clearTimeout(t);
291	      }
292	    })();
293	    return () => { cancelled = true; clearTimeout(t); controller.abort(); };
294	    // intentionally NOT in deps: `qty` would re-run the JIT on every
295	    // stepper tap; only refire when the selected barcode changes.
296	    // eslint-disable-next-line react-hooks/exhaustive-deps
297	  }, [selected?.barcode]);
298	
299	  const results = useMemo(() => {
300	    if (selected) return [];
301	    const q = query.trim().toLowerCase();
302	    // No cap: FlatList virtualizes, so the picker shows every stock item
303	    // when browsing. Capping here (was slice(0, 30)) silently hid items
304	    // for inventories with more than 30 SKUs.
305	    return all.filter((r) => {
306	      if (category !== 'All' && r.category !== category) return false;
307	      if (statusFilter !== 'All') {
308	        const s = statusFor(r);
309	        if (statusFilter === 'In Stock' && s !== 'ok') return false;
310	        if (statusFilter === 'Low' && s !== 'low') return false;
311	        if (statusFilter === 'Out' && s !== 'out') return false;
312	      }
313	      if (!q) return true;
314	      return r.name.toLowerCase().includes(q) || r.barcode.includes(q) || (r.category ?? '').toLowerCase().includes(q);
315	    });
316	  }, [all, query, selected, category, statusFilter]);
317	
318	  const totalTaken = useMemo(
319	    () => allocation.reduce((s, l) => s + (l.take || 0), 0),
320	    [allocation],
321	  );
322	
323	  const totalAvailable = useMemo(
324	    () => availability.reduce((s, l) => s + l.available, 0),
325	    [availability],
326	  );
327	
328	  /** Re-suggest FEFO whenever the user bumps the big "How many?" stepper.
329	   *  This intentionally overwrites manual per-lot edits — the per-lot
330	   *  picker is for fine-tuning AFTER the total is set.
331	   *
332	   *  When the user instead drives the per-lot picker, we sync `qty` to
333	   *  the new sum (see syncQtyFromAllocation). That sync would otherwise
334	   *  trigger this effect and overwrite their lot edit; the ref below
335	   *  swallows exactly one re-suggest pass to break the loop. */
336	  const skipNextFefoRecalc = useRef(false);
337	  useEffect(() => {
338	    if (availability.length === 0) return;
339	    if (skipNextFefoRecalc.current) {
340	      skipNextFefoRecalc.current = false;
341	      return;
342	    }
343	    setAllocation(suggestFEFO(availability, qty));
344	    // eslint-disable-next-line react-hooks/exhaustive-deps
345	  }, [qty]);
346	
347	  /** Per-lot edit handler — keeps the "How many?" stepper in lockstep
348	   *  with the sum of per-lot takes. Without this, the two surfaces drift:
349	   *  the upper stepper says "1" while the picker says "Taken 4 of 1". */
350	  const onAllocationChange = useCallback(
351	    (next: typeof allocation) => {
352	      const sum = next.reduce((s, l) => s + (l.take || 0), 0);
353	      if (sum !== qty) {
354	        skipNextFefoRecalc.current = true;
355	        setQty(sum);
356	      }
357	      setAllocation(next);
358	    },
359	    [qty, allocation],
360	  );
361	
362	  const submit = async () => {
363	    if (!selected || totalTaken <= 0) return;
364	    const session = getSession();
365	    setSaving(true);
366	    try {
367	      const picks = allocation
368	        .filter((l) => l.take > 0)
369	        .map((l) => ({ expiry_date: l.expiry, qty: l.take }));
370	      await enqueue('dispense', {
371	        id: `dsp_${nanoid(12)}`,
372	        barcode: selected.barcode,
373	        product_name: selected.name,
374	        qty: totalTaken,
375	        // Soft-nudge model: server records what the guard actually
376	        // picked rather than enforcing FEFO. Empty picks → server
377	        // falls back to FEFO (the suggestion the user accepted).
378	        lot_picks: picks,
379	        reason,
380	        // taken_by is now always the logged-in guard — no separate
381	        // free-text "who" field. Removes one mandatory input from the
382	        // dispense flow.
383	        taken_by: session?.guardName ?? null,
384	        issued_at: Date.now(),
385	        performed_by: session?.guardId ?? null,
386	        performed_by_name: session?.guardName ?? null,
387	      });
388	      await decrementLotsLocal(
389	        selected.barcode,
390	        totalTaken,
391	        picks.map((p) => ({ expiry_date: p.expiry_date, qty: p.qty })),
392	      );
393	      await adjustOnHand(selected.barcode, -totalTaken);
394	      await flushOnce().catch(() => {});
395	      haptic.success();
396	      navigation.goBack();
397	    } finally {
398	      setSaving(false);
399	    }
400	  };
401	
402	  if (!selected) {
403	    return (
404	      <View style={[styles.safe, { backgroundColor: palette.background }]}>
405	        <AppBar title={t('dispense')} subtitle={t('dispenseSub')} onBack={() => navigation.goBack()} />
406	        <View style={styles.search}>
407	          <TextInput
408	            value={query}
409	            onChangeText={setQuery}
410	            placeholder={t('search')}
411	            placeholderTextColor={palette.onSurfaceVariant}
412	            style={[
413	            styles.searchInput,
414	            {
415	              backgroundColor: palette.surfaceContainerLowest,
416	              borderColor: palette.outlineVariant,
417	              color: palette.onSurface,
418	            },
419	          ]}
420	            autoFocus
421	          />
422	        </View>
423	        <View style={styles.filterRow}>
424	          <FilterDropdown
425	            label={t('filterCategory')}
426	            options={categoryOptions}
427	            selected={category}
428	            onSelect={setCategory}
429	          />
430	          <FilterDropdown
431	            label={t('filterStatus')}
432	            options={statusOptions}
433	            selected={statusFilter}
434	            onSelect={setStatusFilter}
435	          />
436	        </View>
437	        {initialLoading && all.length === 0 ? (
438	          <View style={styles.list}>
439	            {[0, 1, 2, 3].map((i) => (
440	              <View key={i} style={{ marginBottom: spacing.sm }}>
441	                <Card tone="filled" padding="lg">
442	                  <Skeleton width="55%" height={18} />
443	                  <View style={{ height: 6 }} />
444	                  <Skeleton width="75%" height={14} />
445	                </Card>
446	              </View>
447	            ))}
448	          </View>
449	        ) : (
450	          <FlatList
451	            data={results}
452	            keyExtractor={(r) => r.barcode}
453	            contentContainerStyle={styles.list}
454	            refreshControl={
455	              <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={palette.primary} />
456	            }
457	            ItemSeparatorComponent={() => <View style={{ height: spacing.sm }} />}
458	            renderItem={({ item }) => (
459	              <Card tone="filled" padding="lg" onPress={() => setSelected(item)} style={{ backgroundColor: cardBg(item) }}>
460	                <View style={styles.pickerRow}>
461	                  <View style={{ flex: 1 }}>
462	                    <Text variant="titleMedium">{item.name}</Text>
463	                    <Text
464	                      variant="bodyMedium"
465	                      color={palette.onSurfaceVariant}
466	                      style={{ marginTop: 2 }}
467	                    >
468	                      {item.category ?? '—'}
469	                    </Text>
470	                  </View>
471	                  <Text variant="titleLarge" color={countColor(item)} style={{ fontWeight: '700' }}>
472	                    {item.on_hand}
473	                  </Text>
474	                </View>
475	              </Card>
476	            )}
477	            ListEmptyComponent={
478	              <View style={styles.empty}>
479	                <Text variant="bodyLarge" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
480	                  {t('noItemsMatch')}
481	                </Text>
482	              </View>
483	            }
484	          />
485	        )}
486	      </View>
487	    );
488	  }
489	
490	  return (
491	    <View style={[styles.safe, { backgroundColor: palette.background }]}>
492	      <AppBar
493	        title={t('dispense')}
494	        subtitle={selected.name}
495	        onBack={() => setSelected(null)}
496	      />
497	      <KeyboardAvoidingView
498	        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
499	        style={{ flex: 1 }}
500	      >
501	        <ScrollView
502	          contentContainerStyle={[styles.body, { paddingBottom: spacing.xl + kbHeight }]}
503	          keyboardShouldPersistTaps="handled"
504	        >
505	          {/* JIT verification banners. While verifying, the user can
506	              still scroll and pick a reason — they just can't confirm
507	              the dispense yet. */}
508	          {verifyStatus === 'verifying' && (
509	            <View style={styles.statusBanner}>
510	              <ActivityIndicator color={palette.primary} size="small" />
511	              <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginLeft: spacing.sm }}>
512	                {t('verifying')}
513	              </Text>
514	            </View>
515	          )}
516	          {/* Offline / failed check: dispense is still allowed against the
517	              saved count (offline-first), so this is an informational note,
518	              not a blocking error. */}
519	          {(verifyStatus === 'offline' || verifyStatus === 'error') && (
520	            <View
521	              style={[
522	                styles.statusBanner,
523	                { borderColor: palette.outline, backgroundColor: palette.surfaceContainerHigh ?? 'transparent' },
524	              ]}
525	            >
526	              <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
527	                {t('dispenseOfflineNote')}
528	              </Text>
529	            </View>
530	          )}
531	          {/* Absent: the server has no record of this item — dispense stays
532	              blocked. */}
533	          {verifyStatus === 'absent' && (
534	            <View
535	              style={[
536	                styles.statusBanner,
537	                { borderColor: palette.error, backgroundColor: palette.errorContainer ?? 'transparent' },
538	              ]}
539	            >
540	              <Text variant="bodyMedium" color={palette.error}>
541	                {t('itemNotOnServer')}
542	              </Text>
543	            </View>
544	          )}
545	
546	          <Card tone="elevated" padding="xl">
547	            <Text variant="labelLarge" color={palette.onSurfaceVariant}>
548	              {t('product').toUpperCase()}
549	            </Text>
550	            <Text variant="headlineSmall" style={{ marginTop: spacing.xs }}>
551	              {selected.name}
552	            </Text>
553	            <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginTop: spacing.xs }}>
554	              {/* Show the verified on_hand once JIT resolves; fall back
555	                  to the local cache value until then. For divisible
556	                  products the on_hand IS the base unit — just append
557	                  unit. For pack-mode products keep the "N × packSize"
558	                  form. */}
559	              {verifiedOnHand ?? selected.on_hand}
560	              {selected.dispense_mode === 'divisible'
561	                ? selected.unit ? ` ${selected.unit}` : ''
562	                : `${selected.pack_size != null && selected.pack_size !== 1 ? ` × ${selected.pack_size}` : ''}${selected.unit ? ` ${selected.unit}` : ''}`}
563	              {' '}{t('onHand')}
564	            </Text>
565	          </Card>
566	
567	          {/* Quantity area. We can't know whether this is a single-lot
568	              (stepper only) or multi-lot (stepper + per-lot picker)
569	              product until JIT verification returns the lot breakdown.
570	              Rendering the stepper immediately and letting the LotPicker
571	              pop in later is jarring, so while verifying we show a
572	              skeleton placeholder and commit the real controls in one
573	              paint once the breakdown is known. */}
574	          {verifyStatus === 'verifying' ? (
575	            <View style={styles.qtySection}>
576	              <View style={{ alignItems: 'center' }}>
577	                <Skeleton width={120} height={16} />
578	              </View>
579	              <Skeleton width="100%" height={64} rounded="md" />
580	            </View>
581	          ) : (
582	            <>
583	              {/* Primary "How many?" stepper — the familiar input. Max is
584	                  the verified total available across all lots so the user
585	                  can't ask for more than exists. */}
586	              <View style={styles.qtySection}>
587	                <Text variant="labelLarge" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
588	                  {t('howMany').toUpperCase()}
589	                </Text>
590	                <QtyStepper
591	                  value={qty}
592	                  onChange={setQty}
593	                  min={selected.dispense_mode === 'divisible' ? 0.001 : 1}
594	                  max={(totalAvailable || verifiedOnHand || selected.on_hand) || undefined}
595	                  decimal={selected.dispense_mode === 'divisible'}
596	                />
597	              </View>
598	
599	              {/* Per-lot picker. Only worth showing when there are 2+ lots —
600	                  for the common single-lot case the big stepper above is the
601	                  whole story. FEFO is highlighted as "← suggested"; guard
602	                  can override per-row. */}
603	              {availability.length > 1 && (
604	                <LotPicker
605	                  lots={allocation}
606	                  onChange={onAllocationChange}
607	                  desiredQty={qty}
608	                  unit={selected.unit ?? null}
609	                  packSize={selected.pack_size ?? null}
610	                  decimal={selected.dispense_mode === 'divisible'}
611	                />
612	              )}
613	            </>
614	          )}
615	
616	          <View>
617	            <Text variant="labelLarge" color={palette.onSurfaceVariant} style={{ marginBottom: spacing.sm }}>
618	              {t('reason').toUpperCase()}
619	            </Text>
620	            <View style={styles.chipRow}>
621	              {REASONS.map((r) => (
622	                <Chip
623	                  key={r.value}
624	                  label={t(r.labelKey)}
625	                  selected={r.value === reason}
626	                  onPress={() => setReason(r.value)}
627	                />
628	              ))}
629	            </View>
630	          </View>
631	
632	          {/* Who took it: always the logged-in guard. No need for a
633	              text input; just surface their name so they know the
634	              record will be filed under them. */}
635	          <View style={{ marginTop: spacing.md }}>
636	            <Text variant="labelLarge" color={palette.onSurfaceVariant}>
637	              {t('whoTook').toUpperCase()}
638	            </Text>
639	            <Text variant="titleMedium" style={{ marginTop: spacing.xs }}>
640	              {getSession()?.guardName ?? '—'}
641	            </Text>
642	          </View>
643	        </ScrollView>
644	
645	        <View style={[styles.footer, { backgroundColor: palette.surface, borderTopColor: palette.outlineVariant }]}>
646	          {/* Confirm is blocked only while the live check is still running
647	              ('verifying') or when the server has no record of the item
648	              ('absent'). Offline / failed checks fall back to the saved
649	              count and are allowed (offline-first) — the write queues in
650	              the outbox and reconciles on sync. */}
651	          <Button
652	            label={t('confirm')}
653	            onPress={submit}
654	            loading={saving}
655	            disabled={verifyStatus === 'verifying' || verifyStatus === 'absent' || totalTaken <= 0}
656	            size="lg"
657	            fullWidth
658	            leadingIcon={<Check size={22} color={palette.onPrimary} strokeWidth={2.4} />}
659	          />
660	        </View>
661	      </KeyboardAvoidingView>
662	    </View>
663	  );
664	}
665	
666	const styles = StyleSheet.create({
667	  safe: { flex: 1 },
668	  search: { paddingHorizontal: spacing.xl, paddingTop: spacing.sm },
669	  filterRow: {
670	    flexDirection: 'row',
671	    gap: spacing.sm,
672	    paddingHorizontal: spacing.xl,
673	    paddingVertical: spacing.md,
674	  },
675	  searchInput: {
676	    borderRadius: radius.md,
677	    borderWidth: 1.5,
678	    paddingHorizontal: spacing.lg,
679	    minHeight: 52,
680	    fontSize: 17,
681	  },
682	  list: { padding: spacing.xl, paddingBottom: spacing.xxxl },
683	  pickerRow: { flexDirection: 'row', alignItems: 'center', gap: spacing.md },
684	  body: { flexGrow: 1, padding: spacing.xl, gap: spacing.xl },
685	  qtySection: { gap: spacing.lg },
686	  chipRow: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm },
687	  empty: { padding: spacing.xxl },
688	  footer: {
689	    padding: spacing.xl,
690	    borderTopWidth: 1,
691	  },
692	  statusBanner: {
693	    flexDirection: 'row',
694	    alignItems: 'center',
695	    padding: spacing.md,
696	    borderRadius: 8,
697	    borderWidth: 1,
698	    borderColor: 'transparent',
699	  },
700	});
