1	/**
2	 * UnitAwareStepper — A quantity picker that knows about packs and
3	 * base units. Wraps the existing QtyStepper and adds a chip toggle
4	 * so the guard can pick "packs" or "litres" (or "bars", etc.)
5	 * naturally, without any admin pre-configuration.
6	 *
7	 * Replaces the raw QtyStepper + `dispense_mode === 'divisible'`
8	 * checks on DispenseScreen.
9	 *
10	 * If the product can't be subdivided (pack_size ≤ 1), this renders
11	 * a plain QtyStepper with no chips — same UX as today but with the
12	 * decimal/integer decision driven by the unit registry instead of a
13	 * per-product flag.
14	 */
15	
16	import React, { useCallback, useMemo, useState } from 'react';
17	import { StyleSheet, View } from 'react-native';
18	import { Chip } from './Chip';
19	import { QtyStepper } from './QtyStepper';
20	import { Text } from './Text';
21	import { spacing } from './tokens';
22	import { useTheme } from '../theme';
23	import {
24	  canSubdivide,
25	  convertBetweenModes,
26	  isDecimalMode,
27	  maxForMode,
28	  minFor,
29	  packChipLabel,
30	  resolveUnit,
31	  stepSizeFor,
32	  unitChipLabel,
33	} from '../units';
34	
35	export type DispenseMode = 'pack' | 'unit';
36	
37	type Props = {
38	  /** Current quantity value — denomination depends on `mode`. */
39	  value: number;
40	  /**
41	   * Called when the guard changes qty or toggles the pack/unit chip.
