1	/**
2	 * Unit Conversion & Display — Pure functions for pack ↔ base-unit math
3	 * and human-readable stock formatting.
4	 *
5	 * All quantity storage in the system is pack-denominated (on_hand = number
6	 * of packs, possibly fractional). These helpers translate between "packs"
7	 * and "base units" so the UI can display and accept quantities in
8	 * whichever form is most natural for the guard.
9	 */
10	
11	import { resolveUnit, type UnitDef } from './registry';
12	
13	// ─── Conversion ──────────────────────────────────────────────────
14	
15	/** Convert a pack count to base units.  3 packs × 5 kg/pack = 15 kg. */
16	export function packToBase(packs: number, packSize: number): number {
17	  return packs * (packSize > 0 ? packSize : 1);
18	}
19	
20	/** Convert base units to fractional packs.  13 l ÷ 5 l/pack = 2.6 packs. */
21	export function baseToPack(baseUnits: number, packSize: number): number {
22	  const ps = packSize > 0 ? packSize : 1;
23	  return baseUnits / ps;
24	}
25	
26	// ─── Dispense Mode Resolution ────────────────────────────────────
27	
28	/**
29	 * Should the dispense UI show a pack/unit toggle?
30	 *
31	 * True when:
32	 *  - packSize > 1 (there IS a pack to subdivide), AND
33	 *  - the unit is continuous (kg, l — fractional amounts are meaningful),
34	 *    OR the unit is discrete but pack_size > 1 (3-bar pack → can take 1 bar)
35	 *
36	 * False when:
37	 *  - packSize ≤ 1 (single item = no subdivision)
38	 */
39	export function canSubdivide(
40	  packSize: number | null | undefined,
41	  unitSymbol: string | null | undefined,
42	): boolean {
43	  const ps = packSize ?? 1;
44	  if (ps <= 1) return false;
45	  // Any unit with pack_size > 1 can be subdivided — continuous units
46	  // allow decimal sub-amounts, discrete units allow integer sub-amounts.
47	  return true;
48	}
49	
50	/**
51	 * Whether the stepper should allow decimal input for a given mode.
52	 *
53	 * - In 'pack' mode: decimal only if the pack-level on_hand can be
54	 *   fractional (which it can when packs have been partially dispensed).
55	 *   We allow it to let guards correct fractional counts.
56	 * - In 'unit' mode: decimal only if the unit is continuous (kg, l).
57	 */
58	export function isDecimalMode(
59	  mode: 'pack' | 'unit',
60	  unitSymbol: string | null | undefined,
61	): boolean {
62	  const def = resolveUnit(unitSymbol);
63	  if (mode === 'unit') return def.nature === 'continuous';
64	  // Pack mode: allow decimal because fractional packs exist after
65	  // partial dispense (e.g. 2.6 cans). Guard can type 0.4.
66	  return true;
67	}
68	
69	/**
70	 * The step size the +/- buttons should use for a given mode.
71	 *
72	 * Pack mode: always 1 (one whole pack per tap).
73	 * Unit mode: uses the unit registry's minStep (0.1 for kg, 1 for bars).
74	 */
75	export function stepSizeFor(
76	  mode: 'pack' | 'unit',
77	  unitSymbol: string | null | undefined,
78	): number {
79	  if (mode === 'pack') return 1;
80	  return resolveUnit(unitSymbol).minStep;
81	}
82	
83	/**
84	 * Minimum value for the stepper.
85	 * Pack mode: 0.001 (allow tiny fractional for corrections).
86	 * Unit mode: the unit's minStep.
87	 */
88	export function minFor(
89	  mode: 'pack' | 'unit',
90	  unitSymbol: string | null | undefined,
91	): number {
92	  const def = resolveUnit(unitSymbol);
93	  if (mode === 'unit') return def.nature === 'continuous' ? def.minStep : 1;
94	  // Pack mode — any positive value works (fractional packs are real).
95	  return def.nature === 'continuous' ? 0.001 : 1;
96	}
97	
98	/**
99	 * Maximum value for the stepper.
100	 * The available quantity re-expressed in the active mode.
101	 */
102	export function maxForMode(
103	  mode: 'pack' | 'unit',
104	  availablePacks: number,
105	  packSize: number | null | undefined,
106	): number {
107	  if (mode === 'pack') return availablePacks;
108	  return packToBase(availablePacks, packSize ?? 1);
109	}
110	
111	/**
112	 * Convert a value from one mode to the other.
113	 * Used when the guard toggles the pack/unit chip.
114	 */
115	export function convertBetweenModes(
116	  value: number,
117	  fromMode: 'pack' | 'unit',
118	  toMode: 'pack' | 'unit',
119	  packSize: number | null | undefined,
120	): number {
121	  if (fromMode === toMode) return value;
122	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
123	  if (fromMode === 'pack' && toMode === 'unit') return packToBase(value, ps);
124	  return baseToPack(value, ps);
125	}
126	
127	// ─── Display Formatting ──────────────────────────────────────────
128	
129	/**
130	 * Smart-round a number for display. Avoids ugly floating-point dust
131	 * (2.600000001 → 2.6) and keeps up to `maxDecimals` significant digits.
132	 */
133	function smartRound(n: number, maxDecimals: number = 2): number {
134	  if (Number.isInteger(n)) return n;
135	  const factor = Math.pow(10, maxDecimals);
136	  return Math.round(n * factor) / factor;
137	}
138	
139	/**
140	 * Format a single number for display, trimming trailing zeros.
141	 * 2.60 → "2.6", 3.0 → "3", 0.333 → "0.33"
142	 */
143	function formatNum(n: number): string {
144	  return String(smartRound(n));
145	}
146	
147	/**
148	 * Format on_hand for human-readable display.
149	 *
150	 * Handles four cases:
151	 *  1. packSize ≤ 1 → just `"15 kg"` or `"3 pcs"`
152	 *  2. Whole packs → `"3 packs"` (with unit hint: `"3 × 5 kg"`)
153	 *  3. Fractional continuous → `"2 packs + 3 l"` or `"13 l"`
154	 *  4. Fractional discrete → `"3 packs + 1 bar"`
155	 *
156	 * @param onHand   - Current stock in pack-denomination (may be fractional)
157	 * @param packSize - Units per pack (e.g. 5 for 5kg bags)
158	 * @param unit     - Unit symbol (e.g. 'kg', 'pcs')
159	 * @param style    - 'friendly' for app (2 packs + 3 l), 'compact' for dashboard (2.6)
160	 */
161	export function formatOnHand(
162	  onHand: number,
163	  packSize: number | null | undefined,
164	  unit: string | null | undefined,
165	  style: 'friendly' | 'compact' = 'friendly',
166	): string {
167	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
168	  const def = resolveUnit(unit);
169	  const rounded = smartRound(onHand);
170	
171	  // ─── Compact mode (dashboard) ────────────────────────────────
172	  if (style === 'compact') {
173	    if (ps <= 1) return `${formatNum(rounded)} ${def.symbol}`;
174	    return `${formatNum(rounded)}`;
175	  }
176	
177	  // ─── Pack size = 1: no pack/sub-unit split ───────────────────
178	  if (ps <= 1) {
179	    return `${formatNum(rounded)} ${def.symbol}`;
180	  }
181	
182	  // ─── Whole packs ─────────────────────────────────────────────
183	  if (Number.isInteger(rounded) || Math.abs(rounded - Math.round(rounded)) < 0.001) {
184	    const wholePacks = Math.round(rounded);
185	    if (wholePacks === 0) return `0 ${def.symbol}`;
186	    return `${wholePacks} × ${ps} ${def.symbol}`;
187	  }
188	
189	  // ─── Fractional packs ────────────────────────────────────────
190	  const wholePacks = Math.floor(rounded);
191	  const fractionalPacks = smartRound(rounded - wholePacks);
192	  const remainderBaseUnits = smartRound(fractionalPacks * ps);
193	
194	  if (def.nature === 'continuous') {
195	    // "2 packs + 3 l" or "3 l" if 0 whole packs
196	    if (wholePacks === 0) {
197	      return `${formatNum(remainderBaseUnits)} ${def.symbol}`;
198	    }
199	    return `${wholePacks} × ${ps} ${def.symbol} + ${formatNum(remainderBaseUnits)} ${def.symbol}`;
200	  }
201	
202	  // Discrete: "3 packs + 1 bar"
203	  const remainderInt = Math.round(remainderBaseUnits);
204	  if (wholePacks === 0) {
205	    return `${remainderInt} ${def.symbol}`;
206	  }
207	  if (remainderInt === 0) {
208	    return `${wholePacks} × ${ps} ${def.symbol}`;
209	  }
210	  return `${wholePacks} × ${ps} ${def.symbol} + ${remainderInt} ${def.symbol}`;
211	}
212	
213	/**
214	 * Short on-hand label for list items (stock picker, alerts).
215	 * Returns just the number + unit, e.g. "15 l" or "3".
216	 *
217	 * For pack_size > 1, shows the total in base units when the unit is
218	 * continuous, or the pack count otherwise.
219	 */
220	export function formatOnHandShort(
221	  onHand: number,
222	  packSize: number | null | undefined,
223	  unit: string | null | undefined,
224	): string {
225	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
226	  const def = resolveUnit(unit);
227	
228	  if (ps <= 1) {
229	    const u = def.symbol;
230	    return `${formatNum(smartRound(onHand))}${u ? ` ${u}` : ''}`;
231	  }
232	
233	  if (def.nature === 'continuous') {
234	    // Show total base units: 2.6 cans × 5 l = 13 l
235	    const total = smartRound(onHand * ps);
236	    return `${formatNum(total)} ${def.symbol}`;
237	  }
238	
239	  // Discrete with pack_size > 1: show pack count
240	  return `${formatNum(smartRound(onHand))}`;
241	}
242	
243	/**
244	 * Pack-size hint for display under the on-hand count.
245	 * Returns e.g. "× 5 kg" or just "kg" for pack_size=1.
246	 */
247	export function packSizeHint(
248	  packSize: number | null | undefined,
249	  unit: string | null | undefined,
250	): string {
251	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
252	  const def = resolveUnit(unit);
253	
254	  if (ps <= 1) return def.symbol;
255	  return `× ${formatNum(ps)} ${def.symbol}`;
256	}
257	
258	/**
259	 * Label for the "pack" chip in the dispense toggle.
260	 * e.g. "pack (5 kg)" or "pack (3 bars)"
261	 */
262	export function packChipLabel(
263	  packSize: number | null | undefined,
264	  unit: string | null | undefined,
265	): string {
266	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
267	  const def = resolveUnit(unit);
268	  return `pack (${formatNum(ps)} ${def.symbol})`;
269	}
270	
271	/**
272	 * Label for the "unit" chip in the dispense toggle.
273	 * e.g. "litres" or "bars"
274	 */
275	export function unitChipLabel(
276	  unit: string | null | undefined,
277	): string {
278	  const def = resolveUnit(unit);
279	  return def.displayName;
280	}
