const clean = n => Math.round(n*1000)/1000;
const packToBase=(p,ps)=>p*(ps>0?ps:1);
const baseToPack=(b,ps)=>b/(ps>0?ps:1);

// Model: divisible product, dispense in unit (kg) mode, step 0.1
function flow(ps, onHandPacks){
  const oneUnitInPacks = 1/ps;          // start at 1 kg
  let qty = Math.min(onHandPacks, oneUnitInPacks); // packs
  const step = 0.1;
  const seq = [];
  const show = () => clean(packToBase(qty, ps));
  seq.push('start='+show());
  for (const dir of [+1,+1,+1,-1,-1]) {          // tap +,+,+,-,-
    const base = clean(show() + dir*step);
    qty = baseToPack(base, ps);                  // store full precision
    seq.push((dir>0?'+':'-')+'='+show());
  }
  return `ps=${ps}, stock=${onHandPacks}pk: ` + seq.join('  ');
}
console.log(flow(5, 2));   // 5kg bag, 2 in stock
console.log(flow(6, 3));   // 6-unit pack
console.log(flow(3, 10));  // 3-unit pack
console.log(flow(5, 0.1)); // low stock: 0.5 kg left

