1	import * as Network from 'expo-network';
2	import { config } from '../config';
3	import { OutboxKind } from '../db/outbox';
4	import { markFailed, markSending, markSent, nextBatch, pendingCount, recoverOrphanedSending } from '../db/outbox';
5	import { replaceCanonicalProducts, type CanonicalProduct } from '../db/catalog';
6	import { upsertOrdersFromRemote } from '../db/orders';
7	import { replaceStockFromRemote } from '../db/stock';
8	import { pruneLotsToBarcodes, replaceLotsLocal } from '../db/lots';
9	import { api } from './api';
10	import { getSession } from '../auth/session';
11	import { cache, type CacheKey } from './cacheStatus';
12	import { invalidateRefetchThrottle } from './refetch';
13	
14	type Listener = (count: number, lastSyncAt: number | null) => void;
15	
16	let timer: ReturnType<typeof setInterval> | null = null;
17	let readTimer: ReturnType<typeof setInterval> | null = null;
18	let running = false;
19	let retryQueued = false;
20	let _lastSyncAt: number | null = null;
21	const listeners = new Set<Listener>();
22	
23	export function getLastSyncAt(): number | null {
24	  return _lastSyncAt;
25	}
26	
27	export function onPendingChange(l: Listener): () => void {
28	  listeners.add(l);
29	  pendingCount().then((c) => l(c, _lastSyncAt)).catch(() => {});
30	  return () => listeners.delete(l);
31	}
32	
33	async function notify() {
34	  const c = await pendingCount().catch(() => 0);
35	  listeners.forEach((l) => l(c, _lastSyncAt));
36	}
37	
38	// Dispatch table for outbox kinds. Adding a new kind = one line here
39	// + a handler in api.send.*.
40	const DISPATCH: Record<OutboxKind, (payload: object) => Promise<unknown>> = {
41	  receipt: api.send.receipt,
42	  product_registration: api.send.product,
43	  issue: api.send.issue,
44	  dispense: api.send.issue, // same endpoint, renamed in-app
45	  reorder_request: api.send.reorderRequest,
46	  mismatch_flag: api.send.mismatchFlag,
47	  learn_barcode: api.send.learnBarcode,
48	  stock_correction: api.send.stockCorrection,
49	};
50	
51	// Per-kind cache invalidation map. After a successful dispatch we
52	// refetch the listed caches so the local view reflects the server's
53	// truth instead of just the optimistic write — closes the lag where
54	// "I just dispensed, but the Stock list still shows the old count".
55	// Empty list = no read-side cache touched (e.g. learn_barcode is
56	// internal plumbing, no user-visible refresh needed).
57	const POST_WRITE_INVALIDATES: Record<OutboxKind, CacheKey[]> = {
58	  receipt: ['stock', 'orders'],
59	  product_registration: ['catalog'],
60	  issue: ['stock', 'alerts'],
61	  dispense: ['stock', 'alerts'],
62	  reorder_request: ['alerts'],
63	  mismatch_flag: ['orders'],
64	  learn_barcode: [],
65	  stock_correction: ['stock', 'alerts'],
66	};
67	
68	/**
69	 * Pull the freshest read-side data for each touched cache. Called once
70	 * per flushOnce after the outbox batch settles. Each fetch runs in
71	 * parallel and updates its cache state independently so a stock pull
72	 * failing doesn't block an orders pull.
73	 */
74	async function invalidateAffectedCaches(keys: Set<CacheKey>): Promise<void> {
75	  const work: Promise<void>[] = [];
76	  for (const key of keys) {
77	    invalidateRefetchThrottle(key);
78	    work.push(refreshOne(key));
79	  }
80	  await Promise.allSettled(work);
81	}
82	
83	async function refreshOne(key: CacheKey): Promise<void> {
84	  cache.refreshing(key);
85	  try {
86	    if (key === 'stock' || key === 'alerts') {
87	      const remote = await api.fetch.stock();
88	      await replaceStockFromRemote(
89	        remote.map((r) => ({
90	          barcode: r.barcode,
91	          name: r.name,
92	          category: r.category,
93	          unit: r.unit,
94	          pack_size: r.pack_size != null ? Number(r.pack_size) : null,
95	          dispense_mode: r.dispense_mode ?? 'pack',
96	          on_hand: Number(r.on_hand),
97	          threshold: Number(r.threshold),
98	        })),
99	      );
100	      // Mirror per-barcode lots locally too. Empty array clears the
101	      // local lots for that barcode (matches server having no batches).
102	      for (const r of remote) {
103	        await replaceLotsLocal(
104	          r.barcode,
105	          (r.lots ?? []).map((l) => ({
106	            expiry_date: l.expiry_date,
107	            qty: Number(l.qty),
108	          })),
109	        );
110	      }
111	      await pruneLotsToBarcodes(remote.map((r) => r.barcode));
112	    } else if (key === 'orders') {
113	      await syncOrders();
114	    } else if (key === 'catalog') {
115	      await syncCanonicalProducts();
116	    }
117	    cache.warm(key);
118	  } catch (err) {
119	    const msg = err instanceof Error ? err.message : String(err);
120	    if (
121	      msg.includes('Network request failed') ||
122	      msg.includes('TypeError: Network') ||
123	      msg.includes('Unable to resolve host')
124	    ) {
125	      cache.offline(key);
126	    } else {
127	      cache.error(key);
128	    }
129	  }
130	}
131	
132	/**
133	 * Push the outbox and (optionally) pull read-side data.
134	 *
135	 * `pullReads` controls the trailing catalog + orders GETs. Default true so
136	 * focus-refetch, reconnect, and manual "Sync now" keep data fresh during
137	 * active use. The frequent background timer passes `false` so idle ticks
138	 * only push queued writes (≈free when the outbox is empty) instead of
139	 * re-downloading the full catalog every 30s — read pulls run on the slower
140	 * `readPullIntervalMs` cadence instead. Post-write cache invalidation
141	 * (driven by what actually committed) always runs regardless.
142	 */
143	export async function flushOnce(opts?: { pullReads?: boolean }): Promise<{ sent: number; failed: number }> {
144	  const pullReads = opts?.pullReads ?? true;
145	  if (running) {
146	    // Queue a retry so manual "Sync Now" taps aren't silently dropped.
147	    retryQueued = true;
148	    return { sent: 0, failed: 0 };
149	  }
150	  running = true;
151	  let sent = 0;
152	  let failed = 0;
153	  try {
154	    const net = await Network.getNetworkStateAsync().catch(() => ({ isConnected: false }));
